```java
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class ThreadSafeTimestampFormatter {
    private static final ThreadLocal<SimpleDateFormat> TIMESTAMP_FORMAT = new ThreadLocal<SimpleDateFormat>() {
        @Override
        protected SimpleDateFormat initialValue() {
            SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", new Locale("eng"));
            format.setTimeZone(TimeZone.getTimeZone("UTC"));
            return format;
        }
    };

    public static String formatTimestamp(Date date) {
        SimpleDateFormat sdf = TIMESTAMP_FORMAT.get();
        return sdf.format(date);
    }
}
```

In the solution, the `ThreadSafeTimestampFormatter` class encapsulates the `TIMESTAMP_FORMAT` as a `ThreadLocal` variable. The `formatTimestamp` method retrieves the thread-specific `SimpleDateFormat` instance using `TIMESTAMP_FORMAT.get()` and then formats the given `Date` object using this instance. This ensures that each thread has its own `SimpleDateFormat` instance, making the formatting operation thread-safe.

