먼저, 실행 중인 모든 컨테이너를 나열하고 NATS 서버 명명 패턴과 일치하는 컨테이너를 필터링하는 새로운 함수 `getNatsContainers`를 추가합니다:
```go
func getNatsContainers() ([]string, error) {
	output, err := runCommandNoFatal("docker", "ps", "--filter", "ancestor=nats", "--format", "{{.Names}}")
	if err != nil {
 반환 nil, err
	}

	containerNames := strings.Split(strings.TrimSpace(output), "\n")

	var natsContainers []문자열
	for _, containerName := 범위 containerNames {
 if strings.HasPrefix(containerName, "nats-server-") {
