sub five_div_seq {
    my $n = shift @_;
    my $digit = '5';

    # Initialize an empty array
    my @seq = ();

    # Using reverse and range to start from the smaller of n or 1000 down to 100 with a negative step of 18
    # if the number is divisible by either 9 or 14, and contains the digit 5, add it to the list
    foreach my $num (reverse(min($n, 1000)..100)) {
        if ($num % 9 == 0 || $num % 14 == 0) {
            if (index($num, $digit) != -1) {
                push @seq, $num;
            }
        }
    }

    # count occurrences of '5' in the numbers in the list
    my $result = 0;
    foreach my $s (@seq) {
        my $count = () = $s =~ /$digit/g;
        $result += $count;
    }

    return $result;  # Return the result count
}

# Helper function to get the min value
