```python
import pprint

def _calc_size(unit, size):
    if unit == 'kB':
        return size * (2**10)
    elif unit == 'MB':
        return size * (2**20)
    elif unit == 'GB':
        return size * (2**30)
    elif unit == 'TB':
        return size * (2**40)
    return size


def get_disk(parent, host, community):
    from ecks import Ecks

    ecks = Ecks(community, host, 161, parent)

    data = ecks.get_snmp_data('HOST-RESOURCES-MIB::hrStorageTable')

    results = []

    for item in data:
        if 'HOST-RESOURCES-MIB::hrStorageType' not in item:
            continue

        storage_type = item['HOST-RESOURCES-MIB::hrStorageType']
        if storage_type != '.1.3.6.1.2.1.25.2.1.4':  # hrStorageFixedDisk
            continue

        storage_desc = item['HOST-RESOURCES-MIB::hrStorageDescr']

        # hrStorageSize in allocated units
        storage_size = item['HOST-RESOURCES-MIB::hrStorageSize']

        # hrStorageUsed in allocated units
        storage_used = item['HOST-RESOURCES-MIB::hrStorageUsed']

        unit = 'kB'  # Assume default unit
        if 'HOST-RESOURCES-MIB::hrStorageAllocationUnits' in item:
            # Retrieve allocated unit size in bytes
            unit_size_in_bytes = item['HOST-RESOURCES-MIB::hrStorageAllocationUnits']
            storage_size = _calc_size(unit, storage_size * unit_size_in_bytes)
            storage_used = _calc_size(unit, storage_used * unit_size_in_bytes)

        results.append((storage_type, storage_desc, int(storage_size), int(storage_used)))

    return results
```

This script obtains disk usage information through SNMP with given host and community: Creates an Ecks instance (possible SNMP Timeout and Retries not included), gets the SNMP hrStorageTable, then it checks for each line if it represents a fixed disk. If yes, it retrieves the description, total size, and usage of the disk. Size and usage are being multiplied by the size of the Storage Allocation Units.

