import * as fs from 'fs';

function addValueToVariable(fileName: string, componentName: string, variableName: string, value: number): void {
  const filePath = `path/to/${fileName}`; // Replace with the actual file path
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const componentRegex = new RegExp(`\\b${componentName}\\b`, 'g');
  const variableRegex = new RegExp(`\\b${variableName}\\b`, 'g');

  if (componentRegex.test(fileContent)) {
    const componentStartIndex = fileContent.indexOf(componentName);
    const componentEndIndex = fileContent.indexOf('}', componentStartIndex);
    const componentContent = fileContent.substring(componentStartIndex, componentEndIndex);

    if (variableRegex.test(componentContent)) {
      const variableStartIndex = componentContent.indexOf(variableName);
      const variableEndIndex = componentContent.indexOf(';', variableStartIndex);
      const variableDeclaration = componentContent.substring(variableStartIndex, variableEndIndex);

      const currentValue = parseInt(variableDeclaration.match(/\d+/)[0]);
      const updatedValue = currentValue + value;
      const updatedDeclaration = variableDeclaration.replace(/\d+/, updatedValue.toString());

      const updatedFileContent = fileContent.replace(variableDeclaration, updatedDeclaration);
      fs.writeFileSync(filePath, updatedFileContent, 'utf8');
    } else {
      throw new Error(`Variable '${variableName}' not found within component '${componentName}'`);
    }
  } else {
    throw new Error(`Component '${componentName}' not found in file '${fileName}'`);
  }
}
