func calculateAverageScore(scores: [Int]) -> Double {
    let sortedScores = scores.sorted()
    let sum = sortedScores.dropFirst().dropLast().reduce(0, +)
    let average = Double(sum) / Double(sortedScores.count - 2)
    return round(average * 100) / 100
}

