```java
public int[][] resizeImage(int[][] source, int mSampling) {
    int height = source.length;
    int width = source[0].length;
    int scaledWidth = width / mSampling;
    int scaledHeight = height / mSampling;
    int[][] resizedImage = new int[scaledHeight][scaledWidth];

    for (int i = 0; i < scaledHeight; i++) {
        for (int j = 0; j < scaledWidth; j++) {
            int sum = 0;
            for (int k = i * mSampling; k < (i + 1) * mSampling; k++) {
                for (int l = j * mSampling; l < (j + 1) * mSampling; l++) {
                    sum += source[k][l];
                }
            }
            resizedImage[i][j] = sum / (mSampling * mSampling);
        }
    }
    return resizedImage;
}
