from typing import List

def findUniqueVariables(varNameList: List[str]) -> List[str]:
    unique_variables = []
    seen = set()
    for var in varNameList:
        if var not in seen:
            seen.add(var)
        else:
            unique_variables.append(var)
    return list(set(varNameList) - set(unique_variables))
