```python
class Trapezoid:
    def __init__(self, a, b, c, d):
        """Initializes a Trapezoid object"""
        # Check for invalid inputs
        if (a <= 0 or b <= 0 or c <= 0 or d <= 0):
            raise ValueError("Side lengths must be positive")
        self.a = a
        self.b = b
        self.c = c
        self.d = d

    def area(self):
        """Calculates the area of the trapezoid"""
        s = (self.a + self.b + self.c + self.d) / 2 
        area = ((self.a + self.b) / 2) * ((s - self.a) * (s - self.b) * (s - self.c) * (s - self.d)) ** 0.5
        return round(area, 2)

    def perimeter(self):
        """Calculates the perimeter of the trapezoid"""
        return self.a + self.b + self.c + self.d

    def mid_segment(self):
        """Calculates the length of the mid-segment of the trapezoid"""
        return (self.a + self.b) / 2

    def is_isosceles(self):
        """Checks if the trapezoid is isosceles"""
        return self.c == self.d

    def __eq__(self, other):
        return self.area() == other.area()

    def __ne__(self, other):
        return self.area() != other.area()

    def __lt__(self, other):
        return self.area() < other.area()

    def __le__(self, other):
        return self.area() <= other.area()

    def __gt__(self, other):
        return self.area() > other.area()

    def __ge__(self, other):
        return self.area() >= other.area()
```   
