from typing import List, Dict

def version_control(commands: List[str]) -> Dict[str, List[str]]:
    file_versions = {}

    for command in commands:
        action, *args = command.split()
        if action == "commit":
            file_name = args[0]
            if file_name not in file_versions:
                file_versions[file_name] = [f"{file_name}_v1"]
            else:
                latest_version = file_versions[file_name][-1]
                version_number = int(latest_version.split("_v")[1]) + 1
                file_versions[file_name].append(f"{file_name}_v{version_number}")
        elif action == "checkout":
            file_name, version = args
            if file_name in file_versions and int(version) <= len(file_versions[file_name]):
                file_versions[file_name] = file_versions[file_name][:int(version)]

    return file_versions
```

Increase the difficulty of the given programming test question by modifying the task to include both potential swaps and the number of necessary swaps to correct the order:

Complete the following code:

def can_arrange(arr):
    """Create a function that returns a dictionary containing the largest index of an element that is not greater than or equal to the element immediately preceding it, the index of the next smallest element that can be swapped to potentially correct the order, and the minimum number of necessary swaps to correctly sort the array. If no unsorted element exists, return {'index': -1, 'swap_with': -1, 'num_swaps': 0}. The given array will not contain duplicate values.

    Examples:
    can_arrange([1,2,4,3,5]) = {'index': 3, 'swap_with': 2, 'num_swaps': 1}
    can_arrange([1,2,3]) = {'index': -1, 'swap_with': -1, 'num_swaps': 0}
    """

def can_arrange(arr):
    index = -1
    swap_with = -1
    num_swaps = 0

    for i in range(1, len(arr)):
        # Check if current element is smaller than previous element
        if arr[i] < arr[i-1]:
            index = i
            break

    # If there is an element that is not in correct order
    if index != -1:
        for j in range(len(arr)):
            # Find the index of the next smallest element
            if arr[j] > arr[index]:
                swap_with = j
                break

        # Calculate minimum number of necessary swaps to sort array
        num_swaps = index - swap_with

    return {'index': index, 'swap_with': swap_with, 'num_swaps': num_swaps}

